/// Every variant recorded for a symbol, with its provenance.
pub fn candidates(symbol: &str) -> Vec<(Signature, &'static str)> {
    VARIANTS
        .iter()
        .filter(|v| v.symbol == symbol)
        .map(|v| (Signature::from_xtensa(v.symbol, v.code), v.source))
        .collect()
}

/// Is there any signature at all for this symbol?
pub fn has(symbol: &str) -> bool {
    VARIANTS.iter().any(|v| v.symbol == symbol)
}
